import{z as o,x as n,o as A,c as s,q as e,j as t,D as a,d as l,s as r,S as i}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"预算与告警","description":"","frontmatter":{"title":"预算与告警","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/ce-budget-alerting.md","filePath":"llm/ce-budget-alerting.md","lastUpdated":1791063341000}'),d={name:"llm/ce-budget-alerting.md"};function p(F,E,D,C,m,h){const B=n("Mermaid");return A(),s("div",null,[E[2]||(E[2]=e('<h1 id="预算与告警" tabindex="-1">预算与告警 <a class="header-anchor" href="#预算与告警" aria-label="Permalink to &quot;预算与告警&quot;">​</a></h1><div class="epigraph"><p>预算是数量控制，计量计费是价格控制；两者管的是同一种失控，执行语义却完全不同，混用会同时得到两者的缺点。</p><footer>—— 据 Weitzman, Prices vs. Quantities, 1974 的工具对照与本仓库过载治理课整理</footer></div><p><a href="/llm/ce-cost-observability">上一课</a>把每请求成本变成分钟级的打点信号，并留了一句「动作在下一课」。信号要接上执行器才有约束力：预算给成本画上限，告警在逼近时敲钟。本课写预算的分层、执行的语义，以及超支时最容易被搞错的那次诊断。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>没有预算，成本随流量线性放大，事故性超支随时发生：客户端 bug 的重试风暴、Agent 的循环调用、一次营销流量峰，都能让日成本翻几倍。有了预算但执行粗暴，是另一场事故：到线硬切断，SLO 承诺内的业务跟着断。缺口是分层预算与分档执行——谁的超支、超到哪一档、触发什么动作，全部事先写死。缺这层设计的结局可预测：一次超支事故后管理层一刀切限额，业务侧绕过计量，账从此对不上。</p><h3 id="分层与分档" tabindex="-1">分层与分档 <a class="header-anchor" href="#分层与分档" aria-label="Permalink to &quot;分层与分档&quot;">​</a></h3><p>预算分三层：租户、功能、全局——下层超支先在层内处置，全局线只被下层失效击穿。执行分两档：软预算触告警与审批（继续跑，人介入），硬预算触自动动作（限流、降级到小模型、拒绝非关键流量），动作的梯度沿用<a href="/llm/sch-overload-degradation">过载与降级课</a>的阶梯与<a href="/llm/sch-priority-fairness">优先级与公平课</a>的租户公平语义——预算执行就是资源执行的账面版。告警规则两条：燃烧率外推，当前消耗速率乘剩余时间对撞预算余额，让「月底才响」变成「超支前半天就响」；异常检测分型，单租户速率突增与单功能单价突增是两种病，见下一节。</p><p><span class="marginnote">燃烧率外推代个数字：月预算 30 万，月度过了三分之一（前 10 天）却已花掉 15 万——日消耗 1.5 万是计划的 1.5 倍，照此外推月底要花 45 万、超支一半。燃烧率告警就是在第 10 天敲钟，而不是等第 25 天余额见底才响；争取来的这 15 天，正好用来查清是流量涨还是单价涨。</span></p>',8)),(A(),t(i,null,{default:a(()=>[r(B,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20SIG%5B%22%E6%89%93%E7%82%B9%E4%BF%A1%E5%8F%B7%22%5D%20--%3E%20BR%7B%22%E7%87%83%E7%83%A7%E7%8E%87%E5%A4%96%E6%8E%A8%E8%B6%85%E7%BA%BF%3F%22%7D%0A%20%20BR%20--%3E%7C%E6%98%AF%7C%20SOFT%5B%22%E8%BD%AF%E9%A2%84%E7%AE%97%EF%BC%9A%E5%91%8A%E8%AD%A6%E4%B8%8E%E5%AE%A1%E6%89%B9%22%5D%0A%20%20SIG%20--%3E%20ANO%7B%22%E5%8D%95%E4%BB%B7%E6%88%96%E9%80%9F%E7%8E%87%E5%BC%82%E5%B8%B8%3F%22%7D%0A%20%20ANO%20--%3E%7C%E6%B5%81%E9%87%8F%E6%B6%A8%7C%20BIZ%5B%22%E4%B8%9A%E5%8A%A1%E5%A4%84%E7%BD%AE%EF%BC%9A%E6%89%A9%E9%A2%84%E7%AE%97%E6%88%96%E9%99%90%E6%B5%81%22%5D%0A%20%20ANO%20--%3E%7C%E5%8D%95%E4%BB%B7%E6%B6%A8%7C%20ENG%5B%22%E5%B7%A5%E7%A8%8B%E5%A4%84%E7%BD%AE%EF%BC%9A%E5%9B%9E%E6%BB%9A%E5%8F%98%E6%9B%B4%22%5D%0A%20%20BR%20--%3E%7C%E5%88%B0%E7%A1%AC%E7%BA%BF%7C%20HARD%5B%22%E7%A1%AC%E9%A2%84%E7%AE%97%EF%BC%9A%E9%99%90%E6%B5%81%2F%E9%99%8D%E7%BA%A7%2F%E6%8B%92%E9%9D%9E%E5%85%B3%E9%94%AE%22%5D%0A%20%20HARD%20--%3E%20GRAD%5B%22%E6%8C%89%E8%BF%87%E8%BD%BD%E9%98%B6%E6%A2%AF%E5%88%86%E7%BA%A7%E5%8A%A8%E4%BD%9C%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[l(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e('<p><span class="marginnote">直觉类比：预算告警像家里电表——总闸跳闸（硬限）防的是灾难，分级告警（软限）防的是月底账单惊吓；只装总闸的家，永远是在收到账单那天才知道自己用了多少。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>上预算的次序：先给存量画像定基线——上一课的双口径聚合跑稳两周，预算才有可信的分母；再分层设线——租户线按业务价值谈，功能线按单位成本乘目标用量算，全局线按毛利约束倒推；然后钉执行语义——每档动作、豁免清单、审批通道写成文档，硬线动作演练过才上线；最后留缓冲——计量有延迟，硬线的触发点要提前于真实上限，把超支窗口吃掉。Weitzman 的对照落成组织设计：价格工具（内部计量计费，用量方自担边际成本）配数量工具（硬限额封总量）；只用数量工具的组织，超支压力全堆在平台方。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>超支的第一反应必须先分型：流量涨还是单价涨。流量涨是业务问题——用量大了，处置是扩预算、限流或向用量方收费；单价涨是工程回归——提示改动让输出翻倍、路由变更把流量推进大模型、缓存命中率崩了，处置是回滚变更。把单价回归当流量问题处理（「加预算吧」）是最贵的误诊：回归在流血，预算在垫付。误诊的根源是只看总账不分型，而分型正是上一课把速率与单价分开聚合的理由——观测课的设计在预算课兑现。硬预算有竞态：计量与扣减之间有窗口，分布式计数有延迟，硬线附近请求可能超量通过，触发点必须提前、缓冲必须显式。</p>',5)),(A(),t(i,null,{default:a(()=>[r(B,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E6%97%A5%E6%88%90%E6%9C%AC%E8%B6%85%E9%A2%84%E7%AE%97%22%5D%20--%3E%20Q%7B%22%E5%85%88%E5%88%86%E5%9E%8B%EF%BC%9A%E9%92%B1%E5%A4%9A%E8%8A%B1%E5%9C%A8%E5%93%AA%EF%BC%9F%22%7D%0A%20%20Q%20--%3E%7C%22token%20%E7%94%A8%E9%87%8F%E6%B6%A8%22%7C%20T1%5B%22%E6%B5%81%E9%87%8F%E5%9E%8B%EF%BC%9A%E5%A2%9E%E9%95%BF%20%2F%20%E9%87%8D%E8%AF%95%E9%A3%8E%E6%9A%B4%20%2F%20Agent%20%E5%BE%AA%E7%8E%AF%22%5D%0A%20%20T1%20--%3E%20T2%5B%22%E4%B8%9A%E5%8A%A1%E5%A4%84%E7%BD%AE%EF%BC%9A%E6%89%A9%E9%A2%84%E7%AE%97%20%2F%20%E9%99%90%E6%B5%81%20%2F%20%E5%90%91%E7%94%A8%E9%87%8F%E6%96%B9%E8%AE%A1%E8%B4%B9%22%5D%0A%20%20Q%20--%3E%7C%22%E5%8D%95%E4%BD%8D%E6%88%90%E6%9C%AC%E6%B6%A8%22%7C%20P1%5B%22%E5%8D%95%E4%BB%B7%E5%9E%8B%EF%BC%9A%E6%8F%90%E7%A4%BA%E5%8F%98%E9%95%BF%20%2F%20%E8%B7%AF%E7%94%B1%E8%BF%9B%E5%A4%A7%E6%A8%A1%E5%9E%8B%20%2F%20%E7%BC%93%E5%AD%98%E5%A4%B1%E6%95%88%22%5D%0A%20%20P1%20--%3E%20P2%5B%22%E5%B7%A5%E7%A8%8B%E5%A4%84%E7%BD%AE%EF%BC%9A%E5%9B%9E%E6%BB%9A%E5%8F%98%E6%9B%B4%EF%BC%8C%E5%85%88%E6%AD%A2%E8%A1%80%E5%86%8D%E8%B0%88%E9%A2%84%E7%AE%97%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[l(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=e('<p><span class="marginnote">组织的提醒：预算会博弈——团队把用量记到别处、把实验折进生产流量。归属规则要可审计，预算执行报表要公开；治理工具的漏洞不补，最后人人都在学规则而不是省成本。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>硬切断对 SLO 内流量构成违约，合同化的服务（收束前会写成条款）必须区分「超额部分拒」与「承诺部分必保」。预算线太紧会诱发降质（偷偷换小模型保预算），质量门禁要与预算联动。告警疲劳与延迟告警同构：线多误报多，真超支没人看——燃烧率外推只对大口径开，小口径走离线报表。最后，预算约束的是成本不是价值：单位经济（下下课）里赚钱的流量不该被一刀切，预算课管守门，值不值是单位账的事。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>预算三层（租户/功能/全局）、执行两档（软告警审批、硬自动动作），动作梯度沿用过载阶梯。</li><li>告警两规则：燃烧率外推提前触达；异常分型——流量涨是业务问题，单价涨是工程回归。</li><li>超支第一反应是分型再处置，把单价回归当流量问题是误诊。</li><li>硬预算有计量竞态，触发点提前、缓冲显式；价格工具与数量工具配着用。</li><li>出处：Weitzman, 1974 的价格与数量对照；降级阶梯与租户公平语义见本仓库过载与降级课、优先级与公平课。</li></ul>',5))])}const u=o(d,[["render",p]]);export{c as __pageData,u as default};
